<?php $pageTitle='Sales'; require '../includes/functions.php'; require_admin(); $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$stmt=$pdo->prepare('SELECT s.*,o.invoice_no,o.customer_name FROM sales s JOIN orders o ON o.id=s.order_id WHERE s.sale_date BETWEEN ? AND ? ORDER BY s.sale_date DESC');$stmt->execute([$from,$to]);$sales=$stmt->fetchAll(); require '_header.php'; ?>
<div class="d-flex justify-content-between no-print"><h1 class="fw-bold">Sales Management</h1><button data-print class="btn btn-yellow">Print / Export Report</button></div><form class="row g-2 my-3 no-print"><div class="col-md-3"><input name="from" type="date" value="<?= e($from) ?>" class="form-control"></div><div class="col-md-3"><input name="to" type="date" value="<?= e($to) ?>" class="form-control"></div><div class="col-md-2"><button class="btn btn-red w-100">Filter</button></div></form><table class="table bg-white"><thead><tr><th>Date</th><th>Invoice</th><th>Customer</th><th>Total</th></tr></thead><tbody><?php $sum=0; foreach($sales as $s): $sum+=$s['total_amount']; ?><tr><td><?= e($s['sale_date']) ?></td><td><?= e($s['invoice_no']) ?></td><td><?= e($s['customer_name']) ?></td><td><?= money($s['total_amount']) ?></td></tr><?php endforeach; ?></tbody></table><h3>Total: <?= money($sum) ?></h3><?php require '_footer.php'; ?>